add_lexicon!(OFFICIAL_LEXICONS, Dict{String,Any}("defs" => Dict{String,Any}("main" => Dict{String,Any}("description" => "(NOTE: this endpoint is under development and WILL change without notice. Don't use it until it is moved out of `unspecced` or your application WILL break) Get additional posts under a thread e.g. replies hidden by threadgate. Based on an anchor post at any depth of the tree, returns top-level replies below that anchor. It does not include ancestors nor the anchor itself. This should be called after exhausting `app.bsky.unspecced.getPostThreadV2`. Does not require auth, but additional metadata and filtering will be applied for authed requests.", "output" => Dict{String,Any}("encoding" => "application/json", "schema" => Dict{String,Any}("properties" => Dict{String,Any}("thread" => Dict{String,Any}("description" => "A flat list of other thread items. The depth of each item is indicated by the depth property inside the item.", "items" => Dict{String,Any}("ref" => "#threadItem", "type" => "ref"), "type" => "array")), "required" => ["thread"], "type" => "object")), "parameters" => Dict{String,Any}("properties" => Dict{String,Any}("anchor" => Dict{String,Any}("description" => "Reference (AT-URI) to post record. This is the anchor post.", "format" => "at-uri", "type" => "string")), "required" => ["anchor"], "type" => "params"), "type" => "query"), "threadItem" => Dict{String,Any}("properties" => Dict{String,Any}("depth" => Dict{String,Any}("description" => "The nesting level of this item in the thread. Depth 0 means the anchor item. Items above have negative depths, items below have positive depths.", "type" => "integer"), "uri" => Dict{String,Any}("format" => "at-uri", "type" => "string"), "value" => Dict{String,Any}("refs" => ["app.bsky.unspecced.defs#threadItemPost"], "type" => "union")), "required" => ["uri", "depth", "value"], "type" => "object")), "id" => "app.bsky.unspecced.getPostThreadOtherV2", "lexicon" => 1))
add_lexicon!(OFFICIAL_LEXICONS, Dict{String,Any}("defs" => Dict{String,Any}("main" => Dict{String,Any}("description" => "(NOTE: this endpoint is under development and WILL change without notice. Don't use it until it is moved out of `unspecced` or your application WILL break) Get posts in a thread. It is based in an anchor post at any depth of the tree, and returns posts above it (recursively resolving the parent, without further branching to their replies) and below it (recursive replies, with branching to their replies). Does not require auth, but additional metadata and filtering will be applied for authed requests.", "output" => Dict{String,Any}("encoding" => "application/json", "schema" => Dict{String,Any}("properties" => Dict{String,Any}("hasOtherReplies" => Dict{String,Any}("description" => "Whether this thread has additional replies. If true, a call can be made to the `getPostThreadOtherV2` endpoint to retrieve them.", "type" => "boolean"), "thread" => Dict{String,Any}("description" => "A flat list of thread items. The depth of each item is indicated by the depth property inside the item.", "items" => Dict{String,Any}("ref" => "#threadItem", "type" => "ref"), "type" => "array"), "threadgate" => Dict{String,Any}("ref" => "app.bsky.feed.defs#threadgateView", "type" => "ref")), "required" => ["thread", "hasOtherReplies"], "type" => "object")), "parameters" => Dict{String,Any}("properties" => Dict{String,Any}("above" => Dict{String,Any}("default" => true, "description" => "Whether to include parents above the anchor.", "type" => "boolean"), "anchor" => Dict{String,Any}("description" => "Reference (AT-URI) to post record. This is the anchor post, and the thread will be built around it. It can be any post in the tree, not necessarily a root post.", "format" => "at-uri", "type" => "string"), "below" => Dict{String,Any}("default" => 6, "description" => "How many levels of replies to include below the anchor.", "maximum" => 20, "minimum" => 0, "type" => "integer"), "branchingFactor" => Dict{String,Any}("default" => 10, "description" => "Maximum of replies to include at each level of the thread, except for the direct replies to the anchor, which are (NOTE: currently, during unspecced phase) all returned (NOTE: later they might be paginated).", "maximum" => 100, "minimum" => 0, "type" => "integer"), "sort" => Dict{String,Any}("default" => "oldest", "description" => "Sorting for the thread replies.", "knownValues" => ["newest", "oldest", "top"], "type" => "string")), "required" => ["anchor"], "type" => "params"), "type" => "query"), "threadItem" => Dict{String,Any}("properties" => Dict{String,Any}("depth" => Dict{String,Any}("description" => "The nesting level of this item in the thread. Depth 0 means the anchor item. Items above have negative depths, items below have positive depths.", "type" => "integer"), "uri" => Dict{String,Any}("format" => "at-uri", "type" => "string"), "value" => Dict{String,Any}("refs" => ["app.bsky.unspecced.defs#threadItemPost", "app.bsky.unspecced.defs#threadItemNoUnauthenticated", "app.bsky.unspecced.defs#threadItemNotFound", "app.bsky.unspecced.defs#threadItemBlocked"], "type" => "union")), "required" => ["uri", "depth", "value"], "type" => "object")), "id" => "app.bsky.unspecced.getPostThreadV2", "lexicon" => 1))
