# cache of XRPC param types per nsid
const _PARAM_TYPES = Dict{String,Dict{String,Any}}()
"""Param-type maps for XRPC URL encoding, derived from the lexicons."""
function param_types_for(nsid::AbstractString)
    key = String(nsid)
    cached = get(_PARAM_TYPES, key, nothing)
    cached !== nothing && return cached
    def = get_def_or_throw(OFFICIAL_LEXICONS, key)
    pdef = get(def, "parameters", nothing)
    out = Dict{String,Any}()
    if pdef isa AbstractDict
        props = get(pdef, "properties", nothing)
        if props isa AbstractDict
            for (k, v) in props
                out[String(k)] = v
            end
        end
    end
    _PARAM_TYPES[key] = out
    return out
end
